package storage

import (
	"context"
	"encoding/json"
	"errors"
	"path"
	"reflect"
	"sort"
	"strings"
	"time"

	"cfw-policy-llm-agent/server/internal/audit"
	"cfw-policy-llm-agent/server/internal/domain"
	"gorm.io/gorm"
)

// PreparationSpec is generated by the server from an accepted finite selector.
// It is a request boundary, not the resolved input or a new execution grant.
type PreparationSpec struct {
	SourceRef      string               `json:"source_ref"`
	ConfigRevision string               `json:"config_revision"`
	Query          domain.ResourceQuery `json:"query"`
	Selected       []PreparedResource   `json:"selected"`
	Boundary       string               `json:"boundary"`
	Direction      string               `json:"direction"`
	DataPolicy     string               `json:"data_policy"`
	FreshAfter     string               `json:"fresh_after,omitempty"`
	AllowMultiple  bool                 `json:"allow_multiple"`
	ResultLimit    int                  `json:"result_limit"`
}

type PreparedResource struct {
	ResourceID   string `json:"resource_id"`
	Region       string `json:"region"`
	ResourceType string `json:"resource_type"`
	AssetID      string `json:"asset_id,omitempty"`
}

// ConnectionGrant contains only local aliases and read scope, never credentials.
// Versions are immutable; registration activates one version for a source.
type ConnectionGrant struct {
	SourceRef       string             `json:"source_ref"`
	ConfigRevision  string             `json:"config_revision"`
	AccountRef      string             `json:"account_ref"`
	ControlPlaneRef string             `json:"control_plane_ref"`
	Regions         []string           `json:"regions"`
	Boundaries      []string           `json:"boundaries"`
	AssetIDs        []string           `json:"asset_ids,omitempty"`
	GatewayIDs      []string           `json:"gateway_ids,omitempty"`
	Assets          []PreparedResource `json:"assets,omitempty"`
	Gateways        []PreparedResource `json:"gateways,omitempty"`
}

type PreparedAuditBinding struct {
	JobID      string               `json:"job_id"`
	SnapshotID string               `json:"snapshot_id"`
	Scope      domain.Scope         `json:"scope"`
	Selection  domain.Selection     `json:"selection"`
	Heads      []AssetHeadVersion   `json:"heads"`
	Input      domain.Input         `json:"-"`
	Manifest   domain.InputManifest `json:"manifest"`
	BoundAt    string               `json:"bound_at"`
}

var preparedAuditColumns = map[string][]string{
	"connection_grant_versions": {"source_ref", "config_revision", "body"},
	"connection_grant_heads":    {"source_ref", "config_revision"},
	"prepared_audit_acceptance": {"job_id", "plan_id", "accepted_at", "profile_watermark", "intent_watermark", "scope_key", "heads_json", "request_digest"},
	"prepared_audit_data":       {"job_id", "snapshot_id", "data_status"},
	"prepared_audit_bindings":   {"job_id", "snapshot_id", "body", "input_body"},
}

func migratePreparedAuditSchema(tx *gorm.DB) error {
	for _, q := range []string{
		`CREATE TABLE IF NOT EXISTS connection_grant_versions(source_ref TEXT NOT NULL,config_revision TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),PRIMARY KEY(source_ref,config_revision))`,
		`CREATE TABLE IF NOT EXISTS connection_grant_heads(source_ref TEXT PRIMARY KEY,config_revision TEXT NOT NULL,FOREIGN KEY(source_ref,config_revision) REFERENCES connection_grant_versions(source_ref,config_revision))`,
		`CREATE TABLE IF NOT EXISTS prepared_audit_acceptance(job_id TEXT PRIMARY KEY REFERENCES e0_jobs(id),plan_id TEXT UNIQUE NOT NULL REFERENCES execution_plans(id),accepted_at TEXT NOT NULL,profile_watermark INTEGER NOT NULL CHECK(profile_watermark>=0),intent_watermark INTEGER NOT NULL CHECK(intent_watermark>=0),scope_key TEXT NOT NULL,heads_json TEXT NOT NULL CHECK(json_valid(heads_json)),request_digest TEXT NOT NULL)`,
		`CREATE TABLE IF NOT EXISTS prepared_audit_data(job_id TEXT PRIMARY KEY REFERENCES e0_jobs(id),snapshot_id TEXT UNIQUE NOT NULL REFERENCES snapshots(id),data_status TEXT NOT NULL CHECK(data_status IN ('complete','partial')))`,
		`CREATE TABLE IF NOT EXISTS prepared_audit_bindings(job_id TEXT PRIMARY KEY REFERENCES e0_jobs(id),snapshot_id TEXT NOT NULL REFERENCES snapshots(id),body TEXT NOT NULL CHECK(json_valid(body)),input_body TEXT NOT NULL CHECK(json_valid(input_body)))`,
	} {
		if err := tx.Exec(q).Error; err != nil {
			return err
		}
	}
	return checkPreparedAuditSchema(tx)
}

func checkPreparedAuditSchema(db *gorm.DB) error {
	for table, columns := range preparedAuditColumns {
		var names []struct{ Name string }
		if err := db.Raw("SELECT name FROM pragma_table_info(?)", table).Scan(&names).Error; err != nil {
			return err
		}
		found := map[string]bool{}
		for _, n := range names {
			found[n.Name] = true
		}
		for _, column := range columns {
			if !found[column] {
				return errors.New("prepared audit schema incomplete; explicit migration required")
			}
		}
	}
	return nil
}

func finiteKeys(values []string, maximum int, required bool) bool {
	if len(values) > maximum || required && len(values) == 0 {
		return false
	}
	seen := map[string]bool{}
	for _, value := range values {
		if !attemptAlias(value) || seen[value] {
			return false
		}
		seen[value] = true
	}
	return true
}

func (s *Store) RegisterConnectionGrant(ctx context.Context, grant ConnectionGrant) error {
	if !attemptAlias(grant.SourceRef) || grant.SourceRef == "local-offline" || !attemptAlias(grant.ConfigRevision) || !attemptAlias(grant.AccountRef) || !attemptAlias(grant.ControlPlaneRef) || !finiteKeys(grant.Regions, 100, true) || len(grant.Boundaries) < 1 || len(grant.Boundaries) > 3 || !finiteKeys(grant.AssetIDs, 10000, false) || !finiteKeys(grant.GatewayIDs, 10000, false) {
		return ErrInputInvalid
	}
	seenBoundaries := map[string]bool{}
	for _, boundary := range grant.Boundaries {
		if !enum(boundary, "internet/in", "internet/out", "nat/out") || seenBoundaries[boundary] {
			return ErrInputInvalid
		}
		seenBoundaries[boundary] = true
	}
	for kind, resources := range map[string][]PreparedResource{"ecs": grant.Assets, "nat_gateway": grant.Gateways} {
		if len(resources) > 10000 {
			return ErrInputInvalid
		}
		seen := map[string]bool{}
		for _, resource := range resources {
			key := resource.Region + "\x00" + resource.ResourceID
			if !attemptAlias(resource.ResourceID) || resource.ResourceType != kind || !containsPrepared(grant.Regions, resource.Region) || resource.AssetID != "" || seen[key] {
				return ErrInputInvalid
			}
			seen[key] = true
		}
	}
	// Canonical ordering makes semantically identical registration idempotent.
	grant.Regions = append([]string(nil), grant.Regions...)
	grant.Boundaries = append([]string(nil), grant.Boundaries...)
	grant.AssetIDs = append([]string(nil), grant.AssetIDs...)
	grant.GatewayIDs = append([]string(nil), grant.GatewayIDs...)
	grant.Assets = append([]PreparedResource(nil), grant.Assets...)
	grant.Gateways = append([]PreparedResource(nil), grant.Gateways...)
	for _, values := range [][]string{grant.Regions, grant.Boundaries, grant.AssetIDs, grant.GatewayIDs} {
		sort.Strings(values)
	}
	for _, resources := range [][]PreparedResource{grant.Assets, grant.Gateways} {
		sort.Slice(resources, func(i, j int) bool {
			return resources[i].Region+"\x00"+resources[i].ResourceID < resources[j].Region+"\x00"+resources[j].ResourceID
		})
	}
	body, err := marshalBounded(grant, 2<<20)
	if err != nil {
		return err
	}
	return s.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		var prior string
		r := tx.Raw("SELECT body FROM connection_grant_versions WHERE source_ref=? AND config_revision=?", grant.SourceRef, grant.ConfigRevision).Scan(&prior)
		if r.Error != nil {
			return r.Error
		}
		if r.RowsAffected != 0 && prior != string(body) {
			return ErrConflict
		}
		if r.RowsAffected == 0 {
			if err := tx.Exec("INSERT INTO connection_grant_versions(source_ref,config_revision,body) VALUES(?,?,?)", grant.SourceRef, grant.ConfigRevision, string(body)).Error; err != nil {
				return err
			}
		}
		return tx.Exec("INSERT INTO connection_grant_heads(source_ref,config_revision) VALUES(?,?) ON CONFLICT(source_ref) DO UPDATE SET config_revision=excluded.config_revision", grant.SourceRef, grant.ConfigRevision).Error
	})
}

func activeConnectionGrant(tx *gorm.DB, source, revision string) (grant ConnectionGrant, err error) {
	var body string
	r := tx.Raw("SELECT v.body FROM connection_grant_versions v JOIN connection_grant_heads h ON h.source_ref=v.source_ref AND h.config_revision=v.config_revision WHERE v.source_ref=? AND v.config_revision=?", source, revision).Scan(&body)
	if r.Error != nil {
		return grant, r.Error
	}
	if r.RowsAffected != 1 || json.Unmarshal([]byte(body), &grant) != nil || grant.SourceRef != source || grant.ConfigRevision != revision {
		return grant, ErrPlanStale
	}
	return grant, nil
}

func containsPrepared(values []string, value string) bool {
	for _, item := range values {
		if item == value {
			return true
		}
	}
	return false
}

func preparationRegions(q domain.ResourceQuery) []string {
	if q.Region != "" {
		return []string{q.Region}
	}
	return q.Regions
}

func preparationIDs(q domain.ResourceQuery) []string {
	if q.ResourceID != "" {
		return []string{q.ResourceID}
	}
	return q.ResourceIDs
}

func validatePreparation(p ExecutionPlan) error {
	spec := p.Preparation
	if spec == nil {
		return nil
	}
	if p.Kind != "audit" || p.ContextReportID != "" || !attemptAlias(spec.SourceRef) || spec.SourceRef == "local-offline" || spec.SourceRef != p.DataSourceID || spec.ConfigRevision != p.ConfigRevision || !attemptAlias(spec.ConfigRevision) || !enum(spec.DataPolicy, "prefer_fresh", "force_refresh") || spec.ResultLimit < 1 || spec.ResultLimit > p.Workload.Limits.AssetsPerBatch || !enum(spec.Boundary, "internet", "nat") || spec.Boundary == "internet" && !enum(spec.Direction, "in", "out") || spec.Boundary == "nat" && spec.Direction != "out" || !p.EffectCeiling.AllowCloudReads || p.EffectCeiling.CloudHTTPAttempts < 1 || p.Mode == "rules_only" && p.EffectCeiling.AllowModelRequests {
		return ErrInputInvalid
	}
	q := spec.Query
	if q.Region != "" && len(q.Regions) != 0 || q.ResourceID != "" && len(q.ResourceIDs) != 0 || !finiteKeys(preparationRegions(q), 100, true) || !finiteKeys(preparationIDs(q), p.Workload.Limits.AssetsPerBatch, false) || !enum(q.ResourceType, "ecs", "nat_gateway") || q.Group != "" || len(q.Tags) > 20 || len(q.Name) > 256 || strings.ContainsAny(q.Name, "\x00\r\n") || spec.Boundary == "internet" && q.ResourceType != "ecs" || spec.Boundary == "nat" && q.ResourceType != "nat_gateway" || q.Name == "" && len(preparationIDs(q)) == 0 && len(q.Tags) == 0 && !(spec.AllowMultiple && q.ResourceType == "ecs") {
		return ErrInputInvalid
	}
	if !spec.AllowMultiple && spec.ResultLimit != 1 || spec.Boundary == "nat" && spec.ResultLimit != 1 || len(spec.Selected) > spec.ResultLimit || len(preparationIDs(q)) > spec.ResultLimit {
		return ErrInputInvalid
	}
	for key, value := range q.Tags {
		if key == "" || len(key) > 256 || len(value) > 256 || strings.ContainsAny(key+value, "\x00\r\n") {
			return ErrInputInvalid
		}
	}
	if spec.FreshAfter != "" {
		at, err := time.Parse(time.RFC3339Nano, spec.FreshAfter)
		if err != nil || at.After(time.Now().UTC()) {
			return ErrInputInvalid
		}
	}
	seen := map[string]bool{}
	for _, selected := range spec.Selected {
		key := selected.Region + "\x00" + selected.ResourceID
		if !attemptAlias(selected.ResourceID) || !containsPrepared(preparationRegions(q), selected.Region) || selected.ResourceType != q.ResourceType || selected.AssetID != "" && !attemptAlias(selected.AssetID) || seen[key] || len(preparationIDs(q)) != 0 && !containsPrepared(preparationIDs(q), selected.ResourceID) {
			return ErrInputInvalid
		}
		seen[key] = true
	}
	return nil
}

func validatePreparationGrant(tx *gorm.DB, p ExecutionPlan) (ConnectionGrant, error) {
	if err := validatePreparation(p); err != nil || p.Preparation == nil {
		return ConnectionGrant{}, ErrInputInvalid
	}
	spec := p.Preparation
	grant, err := activeConnectionGrant(tx, spec.SourceRef, spec.ConfigRevision)
	if err != nil {
		return grant, err
	}
	if !containsPrepared(grant.Boundaries, spec.Boundary+"/"+spec.Direction) {
		return grant, ErrInputInvalid
	}
	for _, region := range preparationRegions(spec.Query) {
		if !containsPrepared(grant.Regions, region) {
			return grant, ErrInputInvalid
		}
	}
	scope := p.PreparedInput.Scope
	if scope.AccountRef != "" && scope.AccountRef != grant.AccountRef || scope.ControlPlaneRef != "" && scope.ControlPlaneRef != grant.ControlPlaneRef || scope.Boundary != "" && scope.Boundary != spec.Boundary || scope.Direction != "" && scope.Direction != spec.Direction || p.PolicyScopeRef != scope.Ref {
		return grant, ErrInputInvalid
	}
	allowed := grant.AssetIDs
	if spec.Boundary == "nat" {
		allowed = grant.GatewayIDs
	}
	for _, id := range preparationIDs(spec.Query) {
		if len(allowed) != 0 && !containsPrepared(allowed, id) {
			return grant, ErrInputInvalid
		}
		restricted := grant.Assets
		if spec.Boundary == "nat" {
			restricted = grant.Gateways
		}
		matched := len(restricted) == 0
		for _, resource := range restricted {
			if resource.ResourceID == id && containsPrepared(preparationRegions(spec.Query), resource.Region) {
				matched = true
			}
		}
		if !matched {
			return grant, ErrInputInvalid
		}
	}
	for _, resource := range spec.Selected {
		if len(allowed) != 0 && !containsPrepared(allowed, resource.ResourceID) {
			return grant, ErrInputInvalid
		}
		if !preparedGrantResource(grant, resource) {
			return grant, ErrInputInvalid
		}
	}
	return grant, nil
}

func preparedGrantResource(grant ConnectionGrant, resource PreparedResource) bool {
	allowed := grant.Assets
	if resource.ResourceType == "nat_gateway" {
		allowed = grant.Gateways
	}
	if len(allowed) == 0 {
		return true
	}
	for _, candidate := range allowed {
		if candidate.ResourceID == resource.ResourceID && candidate.Region == resource.Region && candidate.ResourceType == resource.ResourceType {
			return true
		}
	}
	return false
}

type preparedAcceptance struct {
	JobID, PlanID, AcceptedAt, ScopeKey, HeadsJSON, RequestDigest string
	ProfileWatermark, IntentWatermark                             int64
}

func recordPreparedAcceptance(tx *gorm.DB, p ExecutionPlan, job Job) error {
	if p.Preparation == nil {
		return nil
	}
	if _, err := validatePreparationGrant(tx, p); err != nil {
		return err
	}
	a := preparedAcceptance{JobID: job.ID, PlanID: p.ID, AcceptedAt: job.CreatedAt, RequestDigest: requestDigest(p.Body)}
	if err := tx.Raw("SELECT COALESCE(max(rowid),0) FROM profile_versions").Scan(&a.ProfileWatermark).Error; err != nil {
		return err
	}
	if err := tx.Raw("SELECT COALESCE(max(rowid),0) FROM intent_versions").Scan(&a.IntentWatermark).Error; err != nil {
		return err
	}
	heads := []AssetHeadVersion{}
	if p.PolicyScopeRef != "" && validConfiguredScope(p.PreparedInput.Scope) {
		a.ScopeKey = canonicalBusinessScope(p.PreparedInput.Scope)
		for _, selected := range p.Preparation.Selected {
			if selected.AssetID == "" {
				continue
			}
			head, err := loadAssetHead(tx, a.ScopeKey, selected.AssetID)
			if err != nil {
				return err
			}
			heads = append(heads, head)
		}
	}
	if len(p.Heads) != 0 && !reflect.DeepEqual(p.Heads, heads) {
		return ErrPlanStale
	}
	body, err := marshalBounded(heads, 64<<10)
	if err != nil {
		return err
	}
	return tx.Exec("INSERT INTO prepared_audit_acceptance(job_id,plan_id,accepted_at,profile_watermark,intent_watermark,scope_key,heads_json,request_digest) VALUES(?,?,?,?,?,?,?,?)", a.JobID, a.PlanID, a.AcceptedAt, a.ProfileWatermark, a.IntentWatermark, a.ScopeKey, string(body), a.RequestDigest).Error
}

// ensureResolvedScope activates only the verified actual scope. Other scopes
// for the connection remain active, including concurrent audit preparations.
func ensureResolvedScope(tx *gorm.DB, p ExecutionPlan, scope domain.Scope) error {
	if !validConfiguredScope(scope) {
		return ErrInputInvalid
	}
	if err := validateScopeIdentity(tx, scope); err != nil {
		return err
	}
	var existing string
	if err := tx.Raw("SELECT source_ref FROM configured_scope_catalog WHERE scope_ref=?", scope.Ref).Scan(&existing).Error; err != nil {
		return err
	}
	if existing != "" && existing != p.DataSourceID {
		return ErrConflict
	}
	body, err := marshalBounded(scope, 4096)
	if err != nil {
		return err
	}
	return tx.Exec("INSERT INTO configured_scope_catalog(scope_ref,source_ref,config_revision,body,active) VALUES(?,?,?,?,1) ON CONFLICT(scope_ref) DO UPDATE SET config_revision=excluded.config_revision,active=1", scope.Ref, p.DataSourceID, p.ConfigRevision, string(body)).Error
}

func preparedNameMatches(query string, r domain.Resource) bool {
	if query == "" {
		return true
	}
	names := []string{r.Name}
	keys := []string{"instance_name"}
	if r.ResourceType == "nat_gateway" {
		keys = []string{"nat_gateway_name", "firewall_name"}
	}
	for _, key := range keys {
		if name := r.SourceNames[key]; name != "" {
			names = append(names, name)
		}
	}
	for _, name := range names {
		if query == name {
			return true
		}
		if r.ResourceType == "ecs" && strings.Contains(query, "*") {
			// Only '*' has provider evidence. Escape path.Match metacharacters.
			pattern := strings.NewReplacer("[", "[[]", "?", "[?]", "\\", "\\\\").Replace(query)
			if matches, _ := path.Match(pattern, name); matches {
				return true
			}
		}
	}
	return false
}

func validatePreparedSnapshot(p ExecutionPlan, grant ConnectionGrant, in domain.Input) error {
	spec := p.Preparation
	if spec == nil || in.SourceKind != "live_readonly" || !validConfiguredScope(in.Scope) || in.Scope.AccountRef != grant.AccountRef || in.Scope.ControlPlaneRef != grant.ControlPlaneRef || !containsPrepared(grant.Boundaries, in.Scope.Boundary+"/"+in.Scope.Direction) || in.Scope.Boundary != spec.Boundary || in.Scope.Direction != spec.Direction || p.PolicyScopeRef != "" && in.Scope != p.PreparedInput.Scope {
		return ErrInputInvalid
	}
	if in.Baseline.Version != p.PreparedInput.Baseline.Version || !reflect.DeepEqual(in.Baseline.EnabledChecks, p.PreparedInput.Baseline.EnabledChecks) || !reflect.DeepEqual(in.Baseline.RiskPorts, p.PreparedInput.Baseline.RiskPorts) {
		return ErrInputInvalid
	}
	if spec.FreshAfter != "" {
		minimum, _ := time.Parse(time.RFC3339Nano, spec.FreshAfter)
		collected, err := time.Parse(time.RFC3339Nano, in.CollectedAt)
		if err != nil || collected.Before(minimum) {
			return ErrInputInvalid
		}
	}
	resources := []domain.Resource{}
	if spec.Boundary == "nat" {
		if in.Selection.Kind != "gateway_policy" || len(in.Assets) != 0 || len(in.Selection.AssetIDs) != 0 || in.GatewayMetadata == nil {
			return ErrInputInvalid
		}
		resources = append(resources, *in.GatewayMetadata)
	} else {
		if in.Selection.Kind != "assets" || len(in.Assets) == 0 || len(in.Assets) != len(in.Selection.AssetIDs) {
			return ErrInputInvalid
		}
		selected := map[string]bool{}
		for _, id := range in.Selection.AssetIDs {
			if selected[id] {
				return ErrInputInvalid
			}
			selected[id] = true
		}
		for _, asset := range in.Assets {
			if !selected[asset.ID] || asset.ScopeRef != in.Scope.Ref || !asset.MetadataComplete {
				return ErrInputInvalid
			}
			resources = append(resources, domain.Resource{Provider: in.Scope.Provider, AccountRef: in.Scope.AccountRef, ResourceID: asset.ProviderResourceID, Region: asset.Region, ResourceType: asset.ResourceType, Name: asset.Name, Tags: asset.Tags, LocalAssetID: asset.ID})
		}
	}
	if len(resources) > spec.ResultLimit || !spec.AllowMultiple && len(resources) != 1 || len(spec.Selected) != 0 && len(resources) != len(spec.Selected) || len(preparationIDs(spec.Query)) != 0 && len(resources) != len(preparationIDs(spec.Query)) {
		return ErrInputInvalid
	}
	seen := map[string]bool{}
	for _, resource := range resources {
		key := resource.Region + "\x00" + resource.ResourceID
		if !attemptAlias(resource.ResourceID) || resource.ResourceType != spec.Query.ResourceType || !containsPrepared(preparationRegions(spec.Query), resource.Region) || !containsPrepared(grant.Regions, resource.Region) || resource.Provider != "aliyun" || resource.AccountRef != grant.AccountRef || seen[key] || !preparedNameMatches(spec.Query.Name, resource) {
			return ErrInputInvalid
		}
		seen[key] = true
		if ids := preparationIDs(spec.Query); len(ids) != 0 && !containsPrepared(ids, resource.ResourceID) {
			return ErrInputInvalid
		}
		allowed := grant.AssetIDs
		if spec.Boundary == "nat" {
			allowed = grant.GatewayIDs
		}
		if len(allowed) != 0 && !containsPrepared(allowed, resource.ResourceID) {
			return ErrInputInvalid
		}
		if !preparedGrantResource(grant, PreparedResource{ResourceID: resource.ResourceID, Region: resource.Region, ResourceType: resource.ResourceType}) {
			return ErrInputInvalid
		}
		for key, value := range spec.Query.Tags {
			actual, ok := resource.Tags[key]
			if !ok || value != "" && actual != value {
				return ErrInputInvalid
			}
		}
		if len(spec.Selected) != 0 {
			matched := false
			for _, accepted := range spec.Selected {
				if accepted.ResourceID == resource.ResourceID && accepted.Region == resource.Region && accepted.ResourceType == resource.ResourceType && (accepted.AssetID == "" || accepted.AssetID == resource.LocalAssetID) {
					matched = true
				}
			}
			if !matched {
				return ErrInputInvalid
			}
		}
	}
	return nil
}

// projectPreparedSelection derives a subset only from immutable accepted cloud
// identities. A name/tag discovery request without explicit identities must
// prove its complete result; it cannot turn a broad snapshot into the first N.
func projectPreparedSelection(p ExecutionPlan, in domain.Input) (domain.Input, error) {
	spec := p.Preparation
	if spec == nil || spec.Boundary == "nat" || len(spec.Selected) == 0 && len(preparationIDs(spec.Query)) == 0 {
		return in, nil
	}
	if in.Selection.Kind != "assets" {
		return in, ErrInputInvalid
	}
	covered := map[string]bool{}
	for _, id := range in.Selection.AssetIDs {
		if covered[id] {
			return in, ErrInputInvalid
		}
		covered[id] = true
	}
	expected := len(spec.Selected)
	if expected == 0 {
		expected = len(preparationIDs(spec.Query))
	}
	assets := []domain.Asset{}
	ids := []string{}
	seen := map[string]bool{}
	for _, asset := range in.Assets {
		matched := false
		if len(spec.Selected) != 0 {
			for _, accepted := range spec.Selected {
				if asset.ProviderResourceID == accepted.ResourceID && asset.Region == accepted.Region && asset.ResourceType == accepted.ResourceType && (accepted.AssetID == "" || asset.ID == accepted.AssetID) {
					matched = true
				}
			}
		} else {
			matched = containsPrepared(preparationIDs(spec.Query), asset.ProviderResourceID) && containsPrepared(preparationRegions(spec.Query), asset.Region) && asset.ResourceType == spec.Query.ResourceType
		}
		if !matched {
			continue
		}
		identity := asset.Region + "\x00" + asset.ProviderResourceID
		if !covered[asset.ID] || seen[identity] || seen["local\x00"+asset.ID] {
			return in, ErrInputInvalid
		}
		seen[identity], seen["local\x00"+asset.ID] = true, true
		assets, ids = append(assets, asset), append(ids, asset.ID)
	}
	if len(assets) != expected {
		return in, ErrInputInvalid
	}
	// Copying the top-level value changes only selection and its business
	// exceptions. ACLs, references, source versions and original times survive.
	in.Assets = assets
	in.Selection = domain.Selection{Kind: "assets", AssetIDs: ids}
	exceptions := []domain.Exception{}
	for _, exception := range in.Baseline.Exceptions {
		if seen["local\x00"+exception.SubjectRef] {
			exceptions = append(exceptions, exception)
		}
	}
	in.Baseline.Exceptions = exceptions
	return in, nil
}

// SavePreparedCloudSnapshot saves one immutable product of the running audit.
// Saving data does not seal input, end the audit, enqueue work or grant budget.
func (s *Store) SavePreparedCloudSnapshot(ctx context.Context, jobID string, content CloudContent, input domain.Input) (record CloudRecord, err error) {
	if content.Kind != "audit" || content.JobID != jobID || input.SourceKind != "live_readonly" || content.ScopeRef != input.Scope.Ref {
		return record, ErrInputInvalid
	}
	if err = ctx.Err(); err != nil {
		return record, err
	}
	// Reuse the raw artifact and observation validator locally, retaining the
	// actual audit producer kind in every digest and persisted product.
	content.Kind = "collect"
	for _, gap := range input.Completeness.KnownGaps {
		if !cloudCode(gap) {
			return record, ErrInputInvalid
		}
		content.Limitations = append(content.Limitations, gap)
	}
	if !input.Completeness.EnumerationComplete {
		content.Limitations = append(content.Limitations, "COLLECTION_INCOMPLETE")
	}
	if input.Completeness.ObservationConsistency != "observed_stable" {
		content.Limitations = append(content.Limitations, "CONFIGURATION_NOT_STABLE")
	}
	content, err = normalizeCloud(content)
	if err != nil {
		return record, err
	}
	content.Kind = "audit"
	inputBody, err := marshalBounded(input, 5<<20)
	if err != nil {
		return record, err
	}
	if json.Unmarshal(inputBody, &input) != nil {
		return record, ErrInputInvalid
	}
	digest := requestDigest(struct {
		Content          CloudContent
		Source, Revision string
		Raw, Input       json.RawMessage
	}{content, content.SourceRef, content.ConfigRevision, content.RawArtifacts, inputBody})
	err = s.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		job, e := get(tx, jobID)
		if e != nil {
			return e
		}
		old, e := jobCloudResult(tx, jobID)
		if e != nil {
			return e
		}
		if old != nil {
			if old.RequestDigest != digest {
				return ErrConflict
			}
			record = *old
			return nil
		}
		if job.Kind != "audit" || job.Status != "running" {
			return ErrJobTerminal
		}
		if e = batchPublicationOpen(tx, job); e != nil {
			return e
		}
		p, e := planRecord(tx, job.PlanID)
		if e != nil {
			return e
		}
		grant, e := validatePreparationGrant(tx, p)
		if e != nil {
			return e
		}
		if p.ConsumedJobID != job.ID || p.ConversationID != job.ConversationID || p.DataSourceID != content.SourceRef || p.ConfigRevision != content.ConfigRevision {
			return ErrInputInvalid
		}
		if e = validatePreparedInput(ctx, p, input); e != nil {
			return e
		}
		if !preparedWindowMatches(p, content) {
			return ErrInputInvalid
		}
		if e = validatePreparedSnapshot(p, grant, input); e != nil {
			return e
		}
		if e = ensureResolvedScope(tx, p, input.Scope); e != nil {
			return e
		}
		snap, e := saveSnapshot(tx, input)
		if e != nil {
			return e
		}
		content.SnapshotID = snap.ID
		id, e := opaqueID("cloud_result")
		if e != nil {
			return e
		}
		body, e := marshalBounded(content, 2<<20)
		if e != nil {
			return e
		}
		record = CloudRecord{ID: id, JobID: jobID, CreatedAt: now(), Content: content, Body: string(body), SourceRef: content.SourceRef, ConfigRevision: content.ConfigRevision, RequestDigest: digest}
		if e = tx.Exec("INSERT INTO job_cloud_results(id,job_id,created_at,source_ref,config_revision,body,raw_artifacts,request_digest) VALUES(?,?,?,?,?,?,?,?)", id, jobID, record.CreatedAt, content.SourceRef, content.ConfigRevision, record.Body, string(content.RawArtifacts), digest).Error; e != nil {
			return e
		}
		status := "partial"
		if preparedDataComplete(input, content) {
			status = "complete"
		}
		if e = tx.Exec("INSERT INTO prepared_audit_data(job_id,snapshot_id,data_status) VALUES(?,?,?)", jobID, snap.ID, status).Error; e != nil {
			return e
		}
		return appendEvent(tx, &job, "stage_changed", map[string]any{"phase": "L1", "stage": "prepared_data_saved", "cloud_result_ref": id})
	})
	return record, err
}

func validatePreparedInput(ctx context.Context, p ExecutionPlan, in domain.Input) error {
	bounded, err := audit.WithInputObjectLimits(ctx, p.Workload.Limits.AssetsPerBatch, p.Workload.Limits.MaxPolicies, p.Workload.Limits.MaxQueryCells)
	if err != nil {
		return ErrInputInvalid
	}
	if err = audit.ValidateContext(bounded, in); err != nil {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		return ErrInputInvalid
	}
	return nil
}

func preparedDataComplete(in domain.Input, content CloudContent) bool {
	if !content.ProductReady || len(content.Limitations) != 0 || !in.Completeness.Declared || !in.Completeness.EnumerationComplete || in.Completeness.ObservationConsistency != "observed_stable" || len(in.Completeness.KnownGaps) != 0 {
		return false
	}
	rounds := map[int]bool{}
	for _, observation := range content.Observations {
		if !observation.EnumerationComplete {
			return false
		}
		if observation.Operation != "DescribeInstances" && observation.Operation != "DescribeSecurityGroupAttribute" {
			rounds[observation.Round] = true
		}
	}
	return rounds[1] && rounds[2]
}

func preparedWindowMatches(p ExecutionPlan, content CloudContent) bool {
	if p.Preparation.FreshAfter == "" {
		return true
	}
	minimum, err := time.Parse(time.RFC3339Nano, p.Preparation.FreshAfter)
	if err != nil || len(content.Observations) == 0 {
		return false
	}
	for _, observation := range content.Observations {
		start, err := time.Parse(time.RFC3339Nano, observation.StartedAt)
		if err != nil || start.Before(minimum) {
			return false
		}
	}
	return true
}

func preparedBinding(tx *gorm.DB, jobID string) (binding PreparedAuditBinding, err error) {
	var row struct{ Body, InputBody string }
	r := tx.Raw("SELECT body,input_body FROM prepared_audit_bindings WHERE job_id=?", jobID).Scan(&row)
	if r.Error != nil {
		return binding, r.Error
	}
	if r.RowsAffected != 1 {
		return binding, ErrNotFound
	}
	if err = json.Unmarshal([]byte(row.Body), &binding); err == nil {
		err = json.Unmarshal([]byte(row.InputBody), &binding.Input)
	}
	return binding, err
}

func (s *Store) GetPreparedAuditBinding(ctx context.Context, jobID string) (PreparedAuditBinding, error) {
	return preparedBinding(s.db.WithContext(ctx), jobID)
}

func eligiblePreparedProducer(tx *gorm.DB, p ExecutionPlan, jobID, snapshotID string) error {
	var row struct{ JobID, Kind, Status, DataStatus string }
	r := tx.Raw("SELECT j.id AS job_id,j.kind,j.status,COALESCE(d.data_status,'') AS data_status FROM job_cloud_results r JOIN e0_jobs j ON j.id=r.job_id LEFT JOIN prepared_audit_data d ON d.job_id=j.id AND d.snapshot_id=? WHERE json_extract(r.body,'$.snapshot_id')=? ORDER BY r.created_at DESC,r.id DESC LIMIT 1", snapshotID, snapshotID).Scan(&row)
	if r.Error != nil {
		return r.Error
	}
	if r.RowsAffected != 1 {
		return ErrInputInvalid
	}
	cloud, err := jobCloudResult(tx, row.JobID)
	if err != nil {
		return err
	}
	if cloud == nil || cloud.SourceRef != p.DataSourceID || cloud.ConfigRevision != p.ConfigRevision || !cloud.Content.IdentityVerified || cloud.Content.Kind != row.Kind || !preparedWindowMatches(p, cloud.Content) {
		return ErrInputInvalid
	}
	if row.JobID == jobID {
		if row.Kind != "audit" || row.Status != "running" || row.DataStatus == "" {
			return ErrInputInvalid
		}
		return nil
	}
	if p.Preparation.DataPolicy == "force_refresh" || !enum(row.Status, "completed", "partial", "failed", "cancelled", "interrupted") || !cloud.Content.ProductReady || len(cloud.Content.Limitations) != 0 || row.Kind == "audit" && row.DataStatus != "complete" || row.Kind == "collect" && row.Status != "completed" || !enum(row.Kind, "audit", "collect") {
		return ErrInputInvalid
	}
	return nil
}

func acceptedBusinessVersion(tx *gorm.DB, table, scopeKey, assetID, exact string, watermark int64, accepted time.Time) (id, body string, err error) {
	var rows []struct{ ID, Body, ConfirmedAt string }
	q := "SELECT id,body,confirmed_at FROM " + table + " WHERE scope_key=? AND asset_key=? AND rowid<=?"
	args := []any{scopeKey, assetID, watermark}
	if exact != "" {
		q += " AND id=?"
		args = append(args, exact)
	}
	if err = tx.Raw(q+" ORDER BY rowid DESC", args...).Scan(&rows).Error; err != nil {
		return
	}
	for _, row := range rows {
		at, e := time.Parse(time.RFC3339Nano, row.ConfirmedAt)
		if e != nil {
			return "", "", ErrInputInvalid
		}
		if !at.After(accepted) {
			return row.ID, row.Body, nil
		}
	}
	if exact != "" {
		return "", "", ErrInputInvalid
	}
	return "", "", nil
}

func applyAcceptedBusiness(tx *gorm.DB, a preparedAcceptance, in domain.Input) (domain.Input, []AssetHeadVersion, error) {
	accepted, err := time.Parse(time.RFC3339Nano, a.AcceptedAt)
	if err != nil {
		return in, nil, ErrInputInvalid
	}
	key := canonicalBusinessScope(in.Scope)
	var frozen []AssetHeadVersion
	if json.Unmarshal([]byte(a.HeadsJSON), &frozen) != nil {
		return in, nil, ErrInputInvalid
	}
	known := map[string]AssetHeadVersion{}
	if key == a.ScopeKey {
		for _, head := range frozen {
			known[head.AssetID] = head
		}
	}
	in.Baseline.Exceptions = []domain.Exception{}
	in.ProfileVersion, in.IntentVersion = "unknown", "unknown"
	heads := []AssetHeadVersion{}
	profiles, intents := []string{}, []string{}
	for i := range in.Assets {
		asset := &in.Assets[i]
		// Cloud snapshots cannot introduce business assertions accepted later.
		asset.AllowedConfirmed, asset.AllowedComplete, asset.DenyAll = false, false, false
		asset.Allowed, asset.Services = []domain.Access{}, []domain.Service{}
		head, precise := known[asset.ID]
		if !precise {
			head = AssetHeadVersion{AssetID: asset.ID}
		}
		if !precise || head.ProfileVersionID != "" {
			id, body, e := acceptedBusinessVersion(tx, "profile_versions", key, asset.ID, head.ProfileVersionID, a.ProfileWatermark, accepted)
			if e != nil {
				return in, nil, e
			}
			head.ProfileVersionID = id
			if id != "" {
				var payload profilePayload
				if json.Unmarshal([]byte(body), &payload) != nil {
					return in, nil, ErrInputInvalid
				}
				applyProfile(asset, payload)
				profiles = append(profiles, asset.ID+"/"+id)
			}
		}
		if !precise || head.IntentVersionID != "" {
			id, body, e := acceptedBusinessVersion(tx, "intent_versions", key, asset.ID, head.IntentVersionID, a.IntentWatermark, accepted)
			if e != nil {
				return in, nil, e
			}
			head.IntentVersionID = id
			if id != "" {
				var payload intentPayload
				if json.Unmarshal([]byte(body), &payload) != nil {
					return in, nil, ErrInputInvalid
				}
				applyIntent(asset, payload, in.Scope.Ref)
				if e = replaceAssetExceptions(&in, asset.ID, payload.Exceptions, false); e != nil {
					return in, nil, e
				}
				intents = append(intents, asset.ID+"/"+id)
			}
		}
		heads = append(heads, head)
	}
	if len(profiles) != 0 {
		sort.Strings(profiles)
		in.ProfileVersion = "profile-set_" + requestDigest(profiles)[:32]
	}
	if len(intents) != 0 {
		sort.Strings(intents)
		in.IntentVersion = "intent-set_" + requestDigest(intents)[:32]
	}
	return in, heads, nil
}

func (s *Store) BindPreparedAuditInput(ctx context.Context, jobID, snapshotID string) (binding PreparedAuditBinding, err error) {
	if !attemptAlias(jobID) || !attemptAlias(snapshotID) {
		return binding, ErrInputInvalid
	}
	err = s.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		old, e := preparedBinding(tx, jobID)
		if e == nil {
			if old.SnapshotID != snapshotID {
				return ErrConflict
			}
			binding = old
			return nil
		}
		if !errors.Is(e, ErrNotFound) {
			return e
		}
		job, e := get(tx, jobID)
		if e != nil {
			return e
		}
		if job.Kind != "audit" || job.Status != "running" {
			return ErrJobTerminal
		}
		if e = batchPublicationOpen(tx, job); e != nil {
			return e
		}
		p, e := planRecord(tx, job.PlanID)
		if e != nil {
			return e
		}
		grant, e := validatePreparationGrant(tx, p)
		if e != nil {
			return e
		}
		if p.ConsumedJobID != job.ID || p.ConversationID != job.ConversationID || p.BudgetRef != job.BudgetRef || !reflect.DeepEqual(p.Workload, job.Workload) {
			return ErrInputInvalid
		}
		var accepted preparedAcceptance
		r := tx.Raw("SELECT * FROM prepared_audit_acceptance WHERE job_id=? AND plan_id=?", jobID, p.ID).Scan(&accepted)
		if r.Error != nil {
			return r.Error
		}
		if r.RowsAffected != 1 || accepted.AcceptedAt != job.CreatedAt || accepted.RequestDigest != requestDigest(p.Body) {
			return ErrInputInvalid
		}
		snap, e := snapshot(tx, snapshotID)
		if e != nil {
			return e
		}
		if e = eligiblePreparedProducer(tx, p, jobID, snapshotID); e != nil {
			return e
		}
		projected, e := projectPreparedSelection(p, snap.Input)
		if e != nil {
			return e
		}
		if e = validatePreparedSnapshot(p, grant, projected); e != nil {
			return e
		}
		in, heads, e := applyAcceptedBusiness(tx, accepted, projected)
		if e != nil {
			return e
		}
		in.EvaluationAt = p.EvaluationAt
		if in.EvaluationAt == "" {
			in.EvaluationAt = now()
		}
		if e = validatePreparedInput(ctx, p, in); e != nil {
			return e
		}
		if e = ensureResolvedScope(tx, p, in.Scope); e != nil {
			return e
		}
		body, e := marshalBounded(in, 5<<20)
		if e != nil {
			return e
		}
		r = tx.Exec("UPDATE e0_jobs SET sealed_input=? WHERE id=? AND status='running' AND sealed_input IS NULL", string(body), jobID)
		if r.Error != nil {
			return r.Error
		}
		if r.RowsAffected != 1 {
			return ErrConflict
		}
		binding = PreparedAuditBinding{JobID: jobID, SnapshotID: snapshotID, Scope: in.Scope, Selection: in.Selection, Heads: heads, Input: in, BoundAt: now(), Manifest: domain.InputManifest{SnapshotVersion: in.SnapshotVersion, ProfileVersion: in.ProfileVersion, IntentVersion: in.IntentVersion, BaselineVersion: in.Baseline.Version, NormalizerVersion: in.NormalizerVersion, KernelVersion: in.KernelVersion, ProviderSemantics: in.Semantics, PolicyScope: in.Scope, EvaluationAt: in.EvaluationAt, CollectedAt: in.CollectedAt, SourceKind: in.SourceKind}}
		bindingBody, e := marshalBounded(binding, 128<<10)
		if e != nil {
			return e
		}
		if e = tx.Exec("INSERT INTO prepared_audit_bindings(job_id,snapshot_id,body,input_body) VALUES(?,?,?,?)", jobID, snapshotID, string(bindingBody), string(body)).Error; e != nil {
			return e
		}
		return appendEvent(tx, &job, "stage_changed", map[string]any{"phase": "L1", "stage": "input_sealed"})
	})
	return binding, err
}
